body {
    margin: 0;
}

.app {
    min-height: 100vh;
    background: var(--g-color-base-background);
    color: var(--g-color-text-primary);
}

.app__header {
    position: sticky;
    top: 0;
    z-index: 1;
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 12px 24px;
    background: var(--g-color-base-background);
    border-bottom: 1px solid var(--g-color-line-generic);
}

.app__nav {
    display: flex;
    gap: 4px;
    flex: 1;
}

.app__content {
    max-width: 880px;
    margin: 0 auto;
    padding: 32px 24px;
}

.page {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.page h1,
.page h2,
.page p {
    margin: 0;
}

.cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 16px;
}

.cards__item {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 20px;
}

.notes-form {
    display: flex;
    gap: 8px;
}

.notes-list {
    list-style: none;
    margin: 0;
    padding: 0;
    border: 1px solid var(--g-color-line-generic);
    border-radius: 8px;
}

.notes-list__item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 8px 8px 8px 16px;
}

.notes-list__item + .notes-list__item {
    border-top: 1px solid var(--g-color-line-generic);
}

/* On narrow screens keep only icons in the nav. */
@media (max-width: 640px) {
    .app__header {
        padding: 8px 12px;
        gap: 8px;
    }

    .app__logo,
    .app__nav-label {
        display: none;
    }
}

